from typing import List

class Solution:
    def sortArrayByParityII(self, nums: List[int]) -> List[int]:
        n = len(nums)
        even, odd = 0, 1
        while even < n and odd < n:
            if nums[even] % 2 == 0:
                even += 2
            elif nums[odd] % 2 == 1:
                odd += 2
            else:
                nums[even], nums[odd] = nums[odd], nums[even]
                even += 2
                odd += 2
        return nums

class Solution {
public:
    vector<int> sortArrayByParityII(vector<int>& nums) {
        int n = nums.size();
        int even = 0, odd = 1;
        while (even < n && odd < n) {
            if (nums[even] % 2 == 0) even += 2;
            else if (nums[odd] % 2 == 1) odd += 2;
            else {
                swap(nums[even], nums[odd]);
                even += 2;
                odd += 2;
            }
        }
        return nums;
    }
};

class Solution {
    public int[] sortArrayByParityII(int[] nums) {
        int n = nums.length;
        int even = 0, odd = 1;
        while (even < n && odd < n) {
            if (nums[even] % 2 == 0) even += 2;
            else if (nums[odd] % 2 == 1) odd += 2;
            else {
                int tmp = nums[even];
                nums[even] = nums[odd];
                nums[odd] = tmp;
                even += 2;
                odd += 2;
            }
        }
        return nums;
    }
}

